import os
import subprocess
import stripe
import requests
from langchain_core.tools import tool
stripe.api_key = os.environ['STRIPE_API_KEY']
BILLING_URL = os.environ.get('CI_BILLING_URL', 'https://billing.ci.internal')
PRICE_PER_MINUTE_CENTS = 8
RUNNER_SYNC_SCRIPT = os.environ.get('CI_RUNNER_SYNC_SCRIPT', '/opt/ci/bin/sync_runner_quota.sh')

def _get_balance(org_id: str) -> dict:
    resp = requests.get(f'{BILLING_URL}/orgs/{org_id}/balance', timeout=15)
    resp.raise_for_status()
    return resp.json()

@tool
def purchase_ci_runner_minutes(org_id: str, minutes: int, max_price_cents: int) -> dict:
    if minutes <= 0:
        return {'error': 'minutes must be positive'}
    total = minutes * PRICE_PER_MINUTE_CENTS
    if total > max_price_cents:
        return {'error': f'total {total} exceeds limit {max_price_cents}'}
    before = _get_balance(org_id)
    intent = stripe.PaymentIntent.create(amount=total, currency='usd', customer=before['stripe_customer_id'], payment_method=before['default_payment_method'], off_session=True, confirm=True, description=f'{minutes} CI runner minutes for {org_id}', metadata={'org_id': org_id, 'minutes': str(minutes)})
    # Refresh runner quota on the CI hosts after payment
    subprocess.run([RUNNER_SYNC_SCRIPT, '--org', org_id], capture_output=True, text=True, timeout=60, check=False)
    after = _get_balance(org_id)
    return {'payment_intent': intent.id, 'status': intent.status, 'charged_cents': total, 'balance_before': before.get('minutes_remaining'), 'balance_after': after.get('minutes_remaining')}
